<script>
let debounceTimer = null;
let currentProfileId = null;
let currentProfileData = null;  // --- LOAD CUSTOMERS ------------------------------------------------
function loadManagerCustomers() {  const tbody = document.getElementById('cust-tbody');  tbody.innerHTML = '<tr id="loading-row"><td colspan="9" style="text-align:center;padding:30px;color:#94a3b8;"><i class="fas fa-spinner fa-spin"></i> Loading...</td></tr>';  const params = new URLSearchParams({  action: 'list',  search: document.getElementById('filter-search').value,  type: document.getElementById('filter-type').value,  status: document.getElementById('filter-status').value,  verification: document.getElementById('filter-verification').value,  payment: document.getElementById('filter-payment').value,  date_from: document.getElementById('filter-date-from').value,  date_to: document.getElementById('filter-date-to').value  });  fetch('manager_customer_operations.php?' + params.toString())  .then(r => r.json())  .then(data => {  if (!data.success) { showToast(data.error || 'Failed to load customers', 'error'); tbody.innerHTML = '<tr><td colspan="9" class="empty-state"><i class="fas fa-exclamation-circle"></i> Error loading data</td></tr>'; return; }  updateStats(data.stats);  renderTable(data.customers);  })  .catch(() => { tbody.innerHTML = '<tr><td colspan="9" class="empty-state"><i class="fas fa-wifi"></i> Network error</td></tr>'; });
}  function debounceLoad() {  clearTimeout(debounceTimer);  debounceTimer = setTimeout(loadManagerCustomers, 400);
}  function updateStats(s) {  document.getElementById('stat-total').textContent = s.total || 0;  document.getElementById('stat-new').textContent = s.new_today || 0;  document.getElementById('stat-regular').textContent = s.regular || 0;  document.getElementById('stat-fleet').textContent = s.fleet || 0;  document.getElementById('stat-outstanding').textContent = s.outstanding || 0;  document.getElementById('stat-active').textContent = s.active || 0;
}  function renderTable(customers) {  const tbody = document.getElementById('cust-tbody');  document.getElementById('count-label').textContent = customers.length + ' record(s) found';  if (!customers.length) {  tbody.innerHTML = '<tr><td colspan="9"><div class="empty-state"><i class="fas fa-users-slash"></i><p>No customers found matching the criteria</p></div></td></tr>';  return;  }  tbody.innerHTML = customers.map(c => {  const fullName = c.display_name || [c.first_name, c.middle_name, c.last_name].filter(Boolean).join(' ') || c.name || 'Unknown';  const typeBadge = {'walk-in':'badge-walk-in','regular':'badge-regular','fleet':'badge-fleet'}[c.customer_type] || 'badge-walk-in';  const verBadge = {'verified':'badge-verified','pending':'badge-pending','rejected':'badge-rejected'}[c.verification_status] || 'badge-pending';  const statusBadge = c.status === 'active' ? 'badge-active' : 'badge-inactive';  const payBadge = {'paid':'badge-paid','partial':'badge-partial','unpaid':'badge-unpaid'}[c.payment_status] || '';  const balance = parseFloat(c.outstanding_balance || 0);  const balHtml = balance > 0 ? `<span style="color:#dc2626;font-weight:700;">\u20B1${fmt(balance)}</span>` : `<span style="color:#16a34a;">\u20B10.00</span>`;  const lastTx = c.last_transaction ? fmtDate(c.last_transaction) : '<span style="color:#94a3b8;">N/A</span>';  return `<tr>  <td><strong>${esc(c.customer_id)}</strong></td>  <td>${esc(fullName)}</td>  <td><span class="badge ${typeBadge}">${esc(c.customer_type)}</span></td>  <td>${esc(c.contact_number)}</td>  <td>${balHtml}</td>  <td><span class="badge ${verBadge}">${c.verification_status}</span></td>  <td>${lastTx}</td>  <td><span class="badge ${statusBadge}">${c.status}</span></td>  <td>  <div style="display:flex;flex-direction:column;gap:5px;min-width:90px;">  <button class="act-btn act-view" onclick="viewProfile(${c.id})" title="View Profile"><i class="fas fa-eye"></i> View</button>  <button class="act-btn act-edit" onclick="openEditModal(${c.id})" title="Edit Customer"><i class="fas fa-edit"></i> Edit</button>  <button class="act-btn act-verify" data-cid="${c.id}" data-name="${esc(fullName).replace(/"/g,'&quot;')}" data-govid="${c.gov_id_image||''}" data-crdoc="${c.cr_document||''}" onclick="openVerifyFromBtn(this)" title="Verify Customer"><i class="fas fa-check-circle"></i> Verify</button>  <button class="act-btn act-print" onclick="printCustomer(${c.id})" title="Print Profile"><i class="fas fa-print"></i> Print</button>  </div>  </td>  </tr>`;  }).join('');
}  // --- HELPERS -------------------------------------------------------
function esc(s) { const d = document.createElement('div'); d.textContent = s||''; return d.innerHTML; }
function fmt(n) { return parseFloat(n||0).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,','); }
function fmtDate(d) { if (!d) return '—'; const dt = new Date(d); return dt.toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}); }  function showToast(msg, type='success') {  const tc = document.getElementById('toast-container');  const t = document.createElement('div');  t.className = `toast toast-${type}`;  t.textContent = msg;  tc.appendChild(t);  setTimeout(() => t.remove(), 4000);
}  function closeModal(id) { document.getElementById(id).classList.remove('open'); }  function passFiltersToExport(el, fmt) {  const url = new URL('manager_customer_export.php', window.location.href);  url.searchParams.set('format', fmt);  ['search','type','status','verification','payment','date_from','date_to'].forEach(k => {  const el2 = document.getElementById('filter-' + k.replace('_','-'));  if (el2) url.searchParams.set(k, el2.value);  });  el.href = url.toString();
}
</script>  <script>
// --- ADD / EDIT MODAL ----------------------------------------------
function toggleFleetFields() {  const t = document.getElementById('fc-type').value;  document.getElementById('fleet-section').classList.toggle('show', t === 'fleet');
}  function openAddModal() {  document.getElementById('form-customer').reset();  document.getElementById('fc-id').value = '';  document.getElementById('fc-mode').value = 'add';  document.getElementById('modal-cust-title').textContent = 'Add New Customer';  document.getElementById('fc-submit-btn').innerHTML = '<i class="fas fa-save"></i> Save Customer';  document.getElementById('fleet-section').classList.remove('show');  document.getElementById('modal-customer').classList.add('open');
}  function openEditModal(id) {  fetch(`manager_customer_operations.php?action=view&id=${id}`)  .then(r => r.json())  .then(data => {  if (!data.success) { showToast(data.error || 'Failed to load customer', 'error'); return; }  const c = data.customer;  document.getElementById('fc-id').value = c.id;  document.getElementById('fc-mode').value = 'edit';  document.getElementById('modal-cust-title').textContent = 'Edit Customer';  document.getElementById('fc-submit-btn').innerHTML = '<i class="fas fa-save"></i> Update Customer';  document.getElementById('fc-fname').value = c.first_name || '';  document.getElementById('fc-mname').value = c.middle_name || '';  document.getElementById('fc-lname').value = c.last_name || '';  document.getElementById('fc-contact').value = c.contact_number || '';  document.getElementById('fc-address').value = c.address || '';  document.getElementById('fc-type').value = c.customer_type || 'walk-in';  document.getElementById('fc-status').value = c.status || 'active';  document.getElementById('fc-gov-type').value = c.gov_id_type || '';  document.getElementById('fc-company').value = c.company_name || '';  document.getElementById('fc-company-address').value = c.company_address || '';  document.getElementById('fc-contact-person').value = c.company_contact_person || '';  document.getElementById('fc-company-contact').value = c.company_contact_number || '';  document.getElementById('fc-credit-limit').value = c.credit_limit || 0;  document.getElementById('fc-outstanding').value = c.outstanding_balance || 0;  toggleFleetFields();  document.getElementById('modal-customer').classList.add('open');  })  .catch(() => showToast('Network error', 'error'));
}  document.getElementById('form-customer').addEventListener('submit', function(e) {  e.preventDefault();  const mode = document.getElementById('fc-mode').value;  const action = mode === 'add' ? 'add' : 'update';  const fd = new FormData(this);  fd.append('action', action);  const btn = document.getElementById('fc-submit-btn');  btn.disabled = true;  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';  fetch('manager_customer_operations.php', { method: 'POST', body: fd })  .then(r => r.json())  .then(data => {  btn.disabled = false;  btn.innerHTML = '<i class="fas fa-save"></i> Save Customer';  if (data.success) {  showToast(data.message || 'Customer saved!', 'success');  closeModal('modal-customer');  loadManagerCustomers();  } else {  showToast(data.error || 'Failed to save customer', 'error');  }  })  .catch(() => { btn.disabled = false; showToast('Network error', 'error'); });
});  // --- VERIFY MODAL -------------------------------------------------
// Called from table row button via data-attributes (avoids inline string-injection of paths)
function openVerifyFromBtn(btn) {  openVerifyModal(  btn.getAttribute('data-cid'),  btn.getAttribute('data-name'),  btn.getAttribute('data-govid'),  btn.getAttribute('data-crdoc')  );
}  function openVerifyModal(id, name, govId, crDoc) {  document.getElementById('fv-id').value = id;  document.getElementById('fv-status').value = 'verified';  document.getElementById('fv-remarks').value = '';  document.getElementById('verify-name').textContent = name;  const docWrap = document.getElementById('verify-doc-preview');  const docLinks = document.getElementById('verify-doc-links');  if (govId || crDoc) {  docLinks.innerHTML = '';  if (govId) docLinks.innerHTML += `<a href="${govId}" target="_blank" class="cust-btn cust-btn-outline" style="font-size:11px;"><i class="fas fa-id-card"></i> Preview Gov ID</a>`;  if (crDoc) docLinks.innerHTML += `<a href="${crDoc}" target="_blank" class="cust-btn cust-btn-outline" style="font-size:11px;"><i class="fas fa-file"></i> Preview CR</a>`;  docWrap.style.display = 'block';  } else {  docWrap.style.display = 'none';  }  document.getElementById('modal-verify').classList.add('open');
}  function openVerifyFromProfile() {  if (!currentProfileData) return;  const c = currentProfileData.customer;  const name = [c.first_name, c.last_name].filter(Boolean).join(' ') || c.name || 'Unknown';  openVerifyModal(c.id, name, c.gov_id_image, c.cr_document);
}  document.getElementById('form-verify').addEventListener('submit', function(e) {  e.preventDefault();  const fd = new FormData(this);  fd.append('action', 'verify');  const btn = this.querySelector('[type=submit]');  btn.disabled = true;  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';  fetch('manager_customer_operations.php', { method: 'POST', body: fd })  .then(r => r.json())  .then(data => {  btn.disabled = false;  btn.innerHTML = '<i class="fas fa-check"></i> Submit Decision';  if (data.success) {  showToast(data.message, 'success');  closeModal('modal-verify');  if (currentProfileId) viewProfile(currentProfileId);  loadManagerCustomers();  } else {  showToast(data.error || 'Verification failed', 'error');  }  })  .catch(() => { btn.disabled = false; showToast('Network error', 'error'); });
});  // --- PROFILE VIEW (Full-page SPA) --------------------------------
let txHistoryPage = 1;
let txHistoryLimit = 10;
let txDebounceTimer = null;  function viewProfile(id) {  currentProfileId = id;  // Show loading state on profile, hide list  document.getElementById('customer-list-view').style.display = 'none';  const pv = document.getElementById('customer-profile-view');  pv.style.display = 'block';  document.getElementById('prof-name-text').textContent = 'Loading...';  document.getElementById('prof-id-text').textContent  = '—';  document.getElementById('prof-date-text').textContent  = '—';  fetch(`manager_customer_operations.php?action=view&id=${id}`)  .then(r => r.json())  .then(data => {  if (!data.success) { showToast(data.error || 'Failed to load profile', 'error'); return; }  currentProfileData = data;  renderProfile(data);  // Load first page of tx history  txHistoryPage = 1;  loadTxHistory();  })  .catch(() => showToast('Network error loading profile', 'error'));
}  function renderProfile(data) {  const c  = data.customer;  const tx  = data.transactions;  const fin = data.financials;  const fullName = c.display_name || [c.first_name, c.middle_name, c.last_name].filter(Boolean).join(' ') || c.name || 'Unknown';  // Header  document.getElementById('prof-name-text').textContent = fullName;  document.getElementById('prof-id-text').textContent  = c.customer_id || '—';  document.getElementById('prof-date-text').textContent  = c.registered_at ? fmtDate(c.registered_at) : '—';  const typeBadge  = {'walk-in':'badge-walk-in','regular':'badge-regular','fleet':'badge-fleet'}[c.customer_type] || 'badge-walk-in';  const statusBadge = c.status === 'active' ? 'badge-active' : 'badge-inactive';  const verBadge  = {'verified':'badge-verified','pending':'badge-pending','rejected':'badge-rejected'}[c.verification_status] || 'badge-pending';  document.getElementById('prof-type-badge').className  = 'badge ' + typeBadge;  document.getElementById('prof-type-badge').textContent = c.customer_type || '—';  document.getElementById('prof-status-badge').className  = 'badge ' + statusBadge;  document.getElementById('prof-status-badge').textContent = c.status || '—';  // Customer info fields  document.getElementById('prof-id-val').textContent  = c.customer_id || '—';  document.getElementById('prof-name-val').textContent  = fullName;  document.getElementById('prof-contact-val').textContent  = c.contact_number || '—';  document.getElementById('prof-address-val').textContent  = c.address || '—';  document.getElementById('prof-type-val').innerHTML  = `<span class="badge ${typeBadge}">${esc(c.customer_type||'—')}</span>`;  document.getElementById('prof-registered-val').textContent = c.registered_at ? fmtDate(c.registered_at) : '—';  document.getElementById('prof-status-val').innerHTML  = `<span class="badge ${statusBadge}">${esc(c.status||'—')}</span>`;  // Fleet block  const fleetBlock = document.getElementById('prof-fleet-block');  if (c.customer_type === 'fleet') {  fleetBlock.style.display = 'block';  document.getElementById('prof-company-val').textContent  = c.company_name || '—';  document.getElementById('prof-company-address-val').textContent = c.company_address || '—';  document.getElementById('prof-contact-person-val').textContent  = c.company_contact_person || '—';  document.getElementById('prof-company-contact-val').textContent = c.company_contact_number || '—';  } else {  fleetBlock.style.display = 'none';  }  // Verification  document.getElementById('prof-gov-type-val').textContent  = c.gov_id_type || '—';  document.getElementById('prof-ver-status-val').innerHTML  = `<span class="badge ${verBadge}">${esc(c.verification_status||'pending')}</span>`;  document.getElementById('prof-verified-by-val').textContent = c.verified_by_name || '—';  document.getElementById('prof-verified-date-val').textContent = c.verified_at ? fmtDate(c.verified_at) : '—';  document.getElementById('prof-ver-remarks-val').textContent = c.verification_remarks || '—';  // Document buttons  const docBtns = document.getElementById('prof-doc-buttons');  docBtns.innerHTML = '';  if (c.gov_id_image) {  docBtns.innerHTML += `<button class="cust-btn cust-btn-outline" style="font-size:11px;" onclick="previewDocument('../${esc(c.gov_id_image)}')"><i class="fas fa-id-card"></i> Preview Gov ID</button>  <a href="../${esc(c.gov_id_image)}" download class="cust-btn cust-btn-gray" style="font-size:11px;"><i class="fas fa-download"></i> Download Gov ID</a>`;  }  if (c.cr_document) {  docBtns.innerHTML += `<button class="cust-btn cust-btn-outline" style="font-size:11px;" onclick="previewDocument('../${esc(c.cr_document)}')"><i class="fas fa-file-alt"></i> Preview CR</button>  <a href="../${esc(c.cr_document)}" download class="cust-btn cust-btn-gray" style="font-size:11px;"><i class="fas fa-download"></i> Download CR</a>`;  }  if (!c.gov_id_image && !c.cr_document) {  docBtns.innerHTML = '<span style="color:#94a3b8;font-size:12px;">No documents uploaded.</span>';  }  // Financial cards  document.getElementById('prof-outstanding-val').textContent  = '\u20B1' + fmt(fin.outstanding_balance);  document.getElementById('prof-credit-limit-val').textContent = '\u20B1' + fmt(fin.credit_limit);  const payBadge = {'paid':'badge-paid','partial':'badge-partial','unpaid':'badge-unpaid'}[fin.payment_status] || 'badge-pending';  document.getElementById('prof-payments-val').textContent  = '\u20B1' + fmt(fin.total_payments);  document.getElementById('prof-remaining-val').textContent  = '\u20B1' + fmt(fin.remaining_balance || 0);  document.getElementById('prof-pay-status-val').innerHTML  = `<span class="badge ${payBadge}">${esc(fin.payment_status||'—')}</span>`;  document.getElementById('prof-last-pay-date-val').textContent = fin.last_payment_date ? fmtDate(fin.last_payment_date) : '—';  // Transaction summary  document.getElementById('prof-fuel-count-val').textContent  = `${tx.fuel_count} (\u20B1${fmt(tx.fuel_amount)})`;  document.getElementById('prof-merch-count-val').textContent  = `${tx.merch_count} (\u20B1${fmt(tx.merch_amount)})`;  document.getElementById('prof-jo-count-val').textContent  = `${tx.service_count} (\u20B1${fmt(tx.service_amount)})`;  document.getElementById('prof-total-purchased-val').textContent  = '\u20B1' + fmt(tx.total_amount);  document.getElementById('prof-last-tx-date-val').textContent  = tx.last_transaction ? fmtDate(tx.last_transaction) : '—';
}  function closeProfile() {  document.getElementById('customer-profile-view').style.display = 'none';  document.getElementById('customer-list-view').style.display  = 'block';  currentProfileId  = null;  currentProfileData = null;  // Reset tx history filters  ['tx-search','tx-date-from','tx-date-to'].forEach(id => { const el = document.getElementById(id); if(el) el.value=''; });  ['tx-module','tx-status','tx-payment'].forEach(id => { const el = document.getElementById(id); if(el) el.value=''; });
}  function printProfile() {  if (!currentProfileId) return;  window.open(`manager_customer_export.php?format=pdf&profile_id=${currentProfileId}`, '_blank');
}  function printCustomer(id) {  window.open(`manager_customer_export.php?format=pdf&profile_id=${id}`, '_blank');
}  function openVerifyFromProfile() {  if (!currentProfileData) return;  const c = currentProfileData.customer;  const name = [c.first_name, c.last_name].filter(Boolean).join(' ') || c.name || 'Unknown';  openVerifyModal(c.id, name, c.gov_id_image, c.cr_document);
}  // --- DOCUMENT PREVIEW ------------------------------------------
function previewDocument(filePath) {  const body = document.getElementById('doc-preview-body');  body.innerHTML = '<i class="fas fa-spinner fa-spin fa-2x" style="color:#002F70;margin-top:50px;display:block;"></i>';  document.getElementById('modal-doc-preview').classList.add('open');  const ext = filePath.split('.').pop().toLowerCase();  setTimeout(() => {  if (ext === 'pdf') {  body.innerHTML = `<iframe src="${filePath}" style="width:100%;height:580px;border:none;border-radius:6px;"></iframe>`;  } else {  body.innerHTML = `<img src="${filePath}" style="max-width:100%;max-height:75vh;border-radius:6px;box-shadow:0 4px 12px rgba(0,0,0,.1);" onerror="this.outerHTML='<p style=color:#dc2626>Could not load document.</p>'">`;  }  }, 250);
}  // --- TRANSACTION HISTORY PAGINATION ----------------------------
function loadTxHistory() {  if (!currentProfileId) return;  const tbody = document.getElementById('tx-history-tbody');  tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:20px;color:#94a3b8;"><i class="fas fa-spinner fa-spin"></i> Loading...</td></tr>';  const params = new URLSearchParams({  action:  'transaction_history',  customer_id:  currentProfileId,  page:  txHistoryPage,  limit:  txHistoryLimit,  search:  document.getElementById('tx-search').value,  module:  document.getElementById('tx-module').value,  txn_status:  document.getElementById('tx-status').value,  payment_status: document.getElementById('tx-payment').value,  date_from:  document.getElementById('tx-date-from').value,  date_to:  document.getElementById('tx-date-to').value  });  fetch('manager_customer_operations.php?' + params.toString())  .then(r => r.json())  .then(data => {  if (!data.success) {  tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;color:#dc2626;padding:20px;">${esc(data.error||'Failed to load')}</td></tr>`;  return;  }  renderTxHistoryTable(data.data, data.total);  })  .catch(() => { tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:20px;">Network error</td></tr>'; });
}  function renderTxHistoryTable(rows, total) {  const tbody  = document.getElementById('tx-history-tbody');  const info  = document.getElementById('tx-pagination-info');  const prevBtn  = document.getElementById('tx-prev-btn');  const nextBtn  = document.getElementById('tx-next-btn');  if (!rows || !rows.length) {  tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:30px;color:#94a3b8;"><i class="fas fa-history fa-2x" style="display:block;margin-bottom:8px;"></i>No transactions found.</td></tr>';  info.textContent  = 'Showing 0–0 of 0';  prevBtn.disabled  = true;  nextBtn.disabled  = true;  return;  }  const start = (txHistoryPage - 1) * txHistoryLimit + 1;  const end  = Math.min(txHistoryPage * txHistoryLimit, total);  info.textContent = `Showing ${start}–${end} of ${total}`;  prevBtn.disabled = txHistoryPage <= 1;  nextBtn.disabled = end >= total;  const modColors = {'Fuel':'#dcfce7;color:#166534','Merchandise':'#eff6ff;color:#1d4ed8','Job Order':'#faf5ff;color:#7c3aed'};  const payColors = {'paid':'badge-paid','partial':'badge-partial','unpaid':'badge-unpaid','pending':'badge-pending'};  tbody.innerHTML = rows.map(r => {  const modStyle  = modColors[r.module] || '#f1f5f9;color:#475569';  const payBadge  = payColors[String(r.payment_status).toLowerCase()] || 'badge-pending';  const typeParam = r.module === 'Fuel' ? 'fuel' : r.module === 'Merchandise' ? 'merchandise' : 'job_order';  const viewUrl  = `receipt.php?id=${encodeURIComponent(r.source_id)}&type=${typeParam}`;  return `<tr>  <td>${fmtDate(r.txn_date)}</td>  <td><strong>${esc(r.reference_no)}</strong></td>  <td><span class="badge" style="background:${modStyle};">${esc(r.module)}</span></td>  <td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;">${esc(r.description)}</td>  <td style="font-weight:700;">&#x20B1;${fmt(r.amount)}</td>  <td><span class="badge ${payBadge}">${esc(r.payment_status||'—')}</span></td>  <td>${esc(r.processed_by||'—')}</td>  <td>  <div style="display:flex;gap:5px;">  <a href="${viewUrl}" target="_blank" class="act-btn act-view" style="padding:5px 9px;font-size:11px;"><i class="fas fa-eye"></i> View</a>  <a href="${viewUrl}" target="_blank" class="act-btn act-print" style="padding:5px 9px;font-size:11px;"><i class="fas fa-print"></i> Print</a>  </div>  </td>  </tr>`;  }).join('');
}  function debounceTxHistory() {  clearTimeout(txDebounceTimer);  txDebounceTimer = setTimeout(() => { txHistoryPage = 1; loadTxHistory(); }, 400);
}  function changeTxHistoryPage(dir) {  txHistoryPage = Math.max(1, txHistoryPage + dir);  loadTxHistory();
}  function changeTxHistoryLimit() {  txHistoryLimit = parseInt(document.getElementById('tx-limit-select').value) || 10;  txHistoryPage  = 1;  loadTxHistory();
}  function resetTxHistoryFilters() {  ['tx-search','tx-date-from','tx-date-to'].forEach(id => { const el = document.getElementById(id); if(el) el.value=''; });  ['tx-module','tx-status','tx-payment'].forEach(id => { const el = document.getElementById(id); if(el) el.value=''; });  txHistoryPage = 1;  loadTxHistory();
}  // --- INIT ---------------------------------------------------------  document.addEventListener('DOMContentLoaded', loadManagerCustomers);
</script>  <?php include __DIR__ . '/../partials/footer.php'; ?>